1	// py-errors.mjs
2	//
3	// Python-shaped error objects and the fatal-error reporting path.
4	//
5	// The reference implementation is a PyInstaller bundle of a CPython script. When
6	// the script raises, CPython writes a traceback to stderr and the interpreter
7	// exits with status 1. This module reproduces the observable contract:
8	//
9	//   * stderr ends with exactly `<ExceptionName>: <message>\n`
10	//   * the process exit status is 1
11	//   * stdout stays empty
12	//
13	// The intermediate `File "...", line N, in f` frame lines are cosmetic (the real
14	// binary emits frozen-module paths that cannot be reproduced), but we emit a
15	// faithfully shaped set so the output reads like a real traceback.
16	
17	import process from 'node:process';
18	
19	/** Successful termination. */
20	export const EXIT_OK = 0;
21	/** An uncaught Python exception reached the top level. */
22	export const EXIT_RUNTIME_ERROR = 1;
23	/** argparse rejected the command line. */
24	export const EXIT_ARG_ERROR = 2;
25	
26	/**
27	 * The analogue of Python's built-in `ValueError`.
28	 *
29	 * `name` is overridden so that traceback rendering and any `instanceof`-free
30	 * duck typing both see the Python spelling rather than `Error`/`PyValueError`.
31	 */
32	export class PyValueError extends Error {
33	  constructor(message) {
34	    super(message);
35	    this.name = 'ValueError';
36	  }
37	}
38	
39	/**
40	 * Render one traceback frame line.
41	 *
42	 * A frame may be given either as a pre-formatted string (used verbatim, so
43	 * callers can paste literal traceback lines) or as `{ file, line, name }`, where
44	 * `file` defaults to the enclosing script's filename.
45	 */
46	function formatFrame(frame, pyFile) {
47	  if (typeof frame === 'string') return frame;
48	  const file = frame.file === undefined ? pyFile : frame.file;
49	  return `  File "${file}", line ${frame.line}, in ${frame.name}`;
50	}
51	
52	/**
53	 * Write a CPython-style traceback for `err` to stderr.
54	 *
55	 * Deliberately does NOT exit: the caller sets `process.exitCode` so that a piped
56	 * stdout/stderr is flushed before the process tears down.
57	 *
58	 * @param {Error} err     the exception to report
59	 * @param {string} pyFile filename used for frames that omit one (e.g. 'test7.py')
60	 * @param {Array<string|{file?: string, line: number|string, name: string}>} frames
61	 *        innermost-last, matching Python's "most recent call last" ordering
62	 */
63	export function pythonFatal(err, pyFile = 'test7.py', frames = []) {
64	  const lines = ['Traceback (most recent call last):'];
65	  for (const frame of frames) lines.push(formatFrame(frame, pyFile));
66	
67	  // Python prints `Name: message`, or a bare `Name` when the message is empty.
68	  const name = err && err.name ? err.name : 'Exception';
69	  const message = err && err.message ? String(err.message) : '';
70	  lines.push(message === '' ? name : `${name}: ${message}`);
71	
72	  process.stderr.write(lines.join('\n') + '\n');
73	}
74

1	// python-bytes.mjs
2	//
3	// The two Python primitives the CLI leans on:
4	//
5	//   * `str.encode()`  -> strict UTF-8 bytes. Every length check in the program
6	//                        ("must be 16 bytes") is against this byte length, never
7	//                        against a JS string's UTF-16 `.length`.
8	//   * `repr(bytes)`   -> the `b'...'` literal that `print()` emits.
9	//
10	// Both are implemented by hand so the module has no dependencies at all.
11	
12	import process from 'node:process';
13	
14	/**
15	 * Exactly Python's `str.encode()` (i.e. `encode('utf-8')`).
16	 *
17	 * Iteration is over UTF-16 code units so that surrogate pairs can be combined
18	 * explicitly and lone surrogates handled deliberately. (`for...of` would hand us
19	 * lone surrogates as-is and tempt an encoder into emitting CESU-8.)
20	 *
21	 * A lone surrogate is encoded as U+FFFD, matching WHATWG `TextEncoder` and
22	 * `Buffer.from(s, 'utf8')`. CPython would instead raise UnicodeEncodeError, but
23	 * that case is unreachable from a Node port: `process.argv` has already replaced
24	 * undecodable argv bytes with U+FFFD before user code runs.
25	 *
26	 * @param {string} str
27	 * @returns {Uint8Array}
28	 */
29	export function encodeUtf8(str) {
30	  const out = [];
31	  for (let i = 0; i < str.length; i++) {
32	    let cp = str.charCodeAt(i);
33	    if (cp >= 0xd800 && cp <= 0xdbff) {
34	      // High surrogate: consume the low surrogate if there is one.
35	      const lo = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
36	      if (lo >= 0xdc00 && lo <= 0xdfff) {
37	        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
38	        i++;
39	      } else {
40	        cp = 0xfffd;
41	      }
42	    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
43	      cp = 0xfffd; // unpaired low surrogate
44	    }
45	
46	    if (cp < 0x80) {
47	      out.push(cp);
48	    } else if (cp < 0x800) {
49	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
50	    } else if (cp < 0x10000) {
51	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
52	    } else {
53	      out.push(
54	        0xf0 | (cp >> 18),
55	        0x80 | ((cp >> 12) & 0x3f),
56	        0x80 | ((cp >> 6) & 0x3f),
57	        0x80 | (cp & 0x3f),
58	      );
59	    }
60	  }
61	  return Uint8Array.from(out);
62	}
63	
64	/**
65	 * Length of `str.encode()` in bytes — i.e. what Python's length checks compare.
66	 *
67	 * @param {string} str
68	 * @returns {number}
69	 */
70	export function utf8ByteLength(str) {
71	  return encodeUtf8(str).length;
72	}
73	
74	const HEX = '0123456789abcdef';
75	const SQ = 0x27; // '
76	const DQ = 0x22; // "
77	const BACKSLASH = 0x5c;
78	
79	/**
80	 * Exactly Python's `repr(bytes)` (CPython's `bytes_repr`). No trailing newline.
81	 *
82	 * @param {Uint8Array|number[]} bytes
83	 * @returns {string} pure ASCII, so any of ascii/latin1/utf8 write encodings match
84	 */
85	export function bytesRepr(bytes) {
86	  // Quote selection scans the whole buffer first: a single quote is used unless
87	  // the payload contains ' and no ", in which case " becomes the delimiter so
88	  // the ' can be written literally.
89	  let hasSingle = false;
90	  let hasDouble = false;
91	  for (let i = 0; i < bytes.length; i++) {
92	    const b = bytes[i];
93	    if (b === SQ) hasSingle = true;
94	    else if (b === DQ) hasDouble = true;
95	  }
96	  const quote = hasSingle && !hasDouble ? DQ : SQ;
97	  const quoteChar = String.fromCharCode(quote);
98	
99	  let out = 'b' + quoteChar;
100	  for (let i = 0; i < bytes.length; i++) {
101	    const b = bytes[i];
102	    if (b === quote || b === BACKSLASH) {
103	      // Must precede the printable-range test: ', " and \ are all printable.
104	      // Note the *other* quote is never escaped, so `\"` is never produced.
105	      out += '\\' + String.fromCharCode(b);
106	    } else if (b === 0x09) {
107	      out += '\\t';
108	    } else if (b === 0x0a) {
109	      out += '\\n';
110	    } else if (b === 0x0d) {
111	      out += '\\r';
112	    } else if (b < 0x20 || b >= 0x7f) {
113	      // Lowercase, always two digits. There are no \a \b \f \v \0 escapes, and
114	      // 0x7f (DEL) is escaped too — hence `>= 0x7f`, not `> 0x7f`.
115	      out += '\\x' + HEX[b >> 4] + HEX[b & 0x0f];
116	    } else {
117	      out += String.fromCharCode(b);
118	    }
119	  }
120	  return out + quoteChar;
121	}
122	
123	/**
124	 * Python's `print(some_bytes)`: the repr followed by exactly one '\n'.
125	 *
126	 * @param {Uint8Array|number[]} bytes
127	 */
128	export function pyPrintBytes(bytes) {
129	  process.stdout.write(bytesRepr(bytes) + '\n');
130	}
