// aes-tables.mjs
//
// GF(2^8) arithmetic and the lookup tables AES is defined over (FIPS-197 §4, §5.1).
//
// Everything here is derived from first principles at module load rather than
// pasted in as 256-entry literals: the field is small enough that the derivation
// is shorter than the tables, and it documents *why* each value is what it is.
// The results are pinned by known-answer assertions in /workspace/verify/t-aes.mjs
// (full S-box table, INV_SBOX[SBOX[i]] === i, Rcon sequence).

/**
 * Multiply by x (i.e. by 2) in GF(2^8).
 *
 * The field's reduction polynomial is x^8 + x^4 + x^3 + x + 1 = 0x11b. The `& 0xff`
 * already discards bit 8, so the value XORed back in is 0x1b, not 0x11b.
 *
 * @param {number} a byte
 * @returns {number} byte
 */
function xtime(a) {
  return ((a << 1) ^ (a & 0x80 ? 0x1b : 0x00)) & 0xff;
}

/**
 * Multiply two bytes in GF(2^8) (carry-less "Russian peasant" multiplication).
 *
 * @param {number} a byte
 * @param {number} b byte
 * @returns {number} byte
 */
export function gmul(a, b) {
  let product = 0;
  let left = a;
  let right = b;
  while (right !== 0) {
    if (right & 1) product ^= left;
    left = xtime(left);
    right >>>= 1;
  }
  return product & 0xff;
}

/** Rotate a byte left by `n` bits. */
function rotl8(value, n) {
  return ((value << n) | (value >>> (8 - n))) & 0xff;
}

/**
 * Build the AES S-box: multiplicative inverse in GF(2^8) followed by the fixed
 * affine transform `b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63`.
 */
function buildSbox() {
  // 0x03 is a primitive element of GF(2^8), so every non-zero byte equals 3^i for
  // exactly one i in 0..254. That gives cheap discrete logs, and hence inverses.
  const antilog = new Uint8Array(255);
  const log = new Uint8Array(256);
  let power = 0x01;
  for (let i = 0; i < 255; i++) {
    antilog[i] = power;
    log[power] = i;
    power = (power ^ xtime(power)) & 0xff; // power *= 3, since 3 = x + 1
  }

  const sbox = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    // 0 has no inverse; AES maps it through the affine part alone (giving 0x63).
    // The `% 255` is load-bearing: for i === 1 we have log[1] === 0, so the index
    // would be 255, one past the end of `antilog`, silently yielding 0.
    const inverse = i === 0 ? 0 : antilog[(255 - log[i]) % 255];
    sbox[i] =
      (inverse ^
        rotl8(inverse, 1) ^
        rotl8(inverse, 2) ^
        rotl8(inverse, 3) ^
        rotl8(inverse, 4) ^
        0x63) &
      0xff;
  }
  return sbox;
}

/** The S-box is a permutation of 0..255, so inverting it is a single pass. */
function buildInverseSbox(sbox) {
  const inverse = new Uint8Array(256);
  for (let i = 0; i < 256; i++) inverse[sbox[i]] = i;
  return inverse;
}

/**
 * Round constants: `RCON[j] = x^(j-1)` in GF(2^8) — 0x01, 0x02, 0x04 ... 0x80,
 * 0x1b, 0x36.
 *
 * Indexed from 1 to match FIPS-197's 1-based Rcon (the key schedule uses
 * `RCON[i / Nk]`, whose smallest value is 1), so slot 0 is unused padding.
 * Ten constants cover all three key sizes: AES-128 uses j = 1..10, AES-192
 * j = 1..8, AES-256 j = 1..7.
 */
function buildRcon(count) {
  const rcon = new Uint8Array(count + 1);
  let power = 0x01;
  for (let j = 1; j <= count; j++) {
    rcon[j] = power;
    power = xtime(power);
  }
  return rcon;
}

/** Substitution box used by SubBytes and SubWord. */
export const SBOX = buildSbox();

/** Inverse substitution box used by InvSubBytes. */
export const INV_SBOX = buildInverseSbox(SBOX);

/** Key-schedule round constants, 1-indexed (see {@link buildRcon}). */
export const RCON = buildRcon(10);

// aes-core.mjs
//
// The AES block cipher (FIPS-197) in pure JavaScript, byte-oriented and written
// to read like the specification: SubBytes / ShiftRows / MixColumns / AddRoundKey
// appear as separate steps rather than being folded into T-tables. Only two
// blocks are ever encrypted per run, so clarity beats throughput.
//
// The API mirrors pyaes's `AES` class, including its ValueError messages.

import { PyValueError } from './py-errors.mjs';
import { SBOX, INV_SBOX, RCON, gmul } from './aes-tables.mjs';

/** AES operates on 128-bit blocks for every key size. */
export const BLOCK_SIZE = 16;

/** Byte lengths accepted for a key: AES-128, AES-192 and AES-256. */
const KEY_SIZES = [16, 24, 32];

// The state is a 4x4 byte matrix held flat, column-major:
//
//     state[r + 4 * c] is row r, column c
//
// which is exactly the order the bytes arrive in, so loading and storing a block
// is a plain copy. Column c is the contiguous run state[4c .. 4c+3]; row r is the
// stride-4 slice starting at r.

/**
 * Expand a cipher key into `4 * (Nr + 1)` round-key words (FIPS-197 §5.2).
 *
 * @param {Uint8Array} key 16, 24 or 32 bytes
 * @returns {{words: Uint8Array[], rounds: number}} words are 4 bytes each; a word
 *          is a *column* of the round key, so `words[k][r]` XORs into row r.
 */
function expandKey(key) {
  const nk = key.length / 4; // key length in words: 4, 6 or 8
  const rounds = nk + 6; // Nr: 10, 12 or 14
  const total = 4 * (rounds + 1);

  const words = [];
  for (let i = 0; i < nk; i++) words.push(key.slice(4 * i, 4 * i + 4));

  for (let i = nk; i < total; i++) {
    const temp = words[i - 1].slice();
    if (i % nk === 0) {
      // RotWord: [a0,a1,a2,a3] -> [a1,a2,a3,a0]
      const first = temp[0];
      temp[0] = SBOX[temp[1]];
      temp[1] = SBOX[temp[2]];
      temp[2] = SBOX[temp[3]];
      temp[3] = SBOX[first];
      temp[0] ^= RCON[i / nk];
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 only: an extra SubWord, with no RotWord and no round constant.
      for (let j = 0; j < 4; j++) temp[j] = SBOX[temp[j]];
    }
    const previous = words[i - nk];
    for (let j = 0; j < 4; j++) temp[j] ^= previous[j];
    words.push(temp);
  }

  return { words, rounds };
}

/** XOR round key `round` into the state. */
function addRoundKey(state, words, round) {
  for (let c = 0; c < 4; c++) {
    const word = words[4 * round + c];
    for (let r = 0; r < 4; r++) state[r + 4 * c] ^= word[r];
  }
}

/** Apply a substitution box to every cell (SubBytes / InvSubBytes). */
function substituteBytes(state, box) {
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] = box[state[i]];
}

/**
 * Rotate row r by r bytes: left when encrypting, right when decrypting.
 *
 * @param {Uint8Array} state
 * @param {number} direction +1 for ShiftRows, -1 for InvShiftRows
 */
function shiftRows(state, direction) {
  for (let r = 1; r < 4; r++) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c++) {
      state[r + 4 * c] = row[(c + direction * r + 4) % 4];
    }
  }
}

/**
 * Mix each column against a fixed polynomial.
 *
 * @param {Uint8Array} state
 * @param {number[]} coefficients first row of the circulant matrix — [2,3,1,1]
 *        for MixColumns, [14,11,13,9] for InvMixColumns; each subsequent row is
 *        the previous one rotated right by one.
 */
function mixColumns(state, coefficients) {
  const [c0, c1, c2, c3] = coefficients;
  for (let c = 0; c < 4; c++) {
    const o = 4 * c;
    // Snapshot the column: every output byte depends on every input byte.
    const a0 = state[o];
    const a1 = state[o + 1];
    const a2 = state[o + 2];
    const a3 = state[o + 3];
    state[o] = gmul(a0, c0) ^ gmul(a1, c1) ^ gmul(a2, c2) ^ gmul(a3, c3);
    state[o + 1] = gmul(a0, c3) ^ gmul(a1, c0) ^ gmul(a2, c1) ^ gmul(a3, c2);
    state[o + 2] = gmul(a0, c2) ^ gmul(a1, c3) ^ gmul(a2, c0) ^ gmul(a3, c1);
    state[o + 3] = gmul(a0, c1) ^ gmul(a1, c2) ^ gmul(a2, c3) ^ gmul(a3, c0);
  }
}

/**
 * Single-block AES, equivalent to pyaes's `pyaes.AES`.
 *
 * The key schedule is computed once in the constructor and reused by every call.
 */
export class AES {
  /**
   * @param {Uint8Array} key 16, 24 or 32 bytes
   * @throws {PyValueError} 'Invalid key size' for any other length
   */
  constructor(key) {
    const keyBytes = Uint8Array.from(key);
    if (KEY_SIZES.indexOf(keyBytes.length) === -1) {
      throw new PyValueError('Invalid key size');
    }
    const { words, rounds } = expandKey(keyBytes);
    this._words = words;
    this._rounds = rounds;
  }

  /**
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} 16 bytes
   * @throws {PyValueError} 'plaintext block must be 16 bytes'
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw new PyValueError('plaintext block must be 16 bytes');
    }
    const state = Uint8Array.from(plaintext);

    addRoundKey(state, this._words, 0);
    for (let round = 1; round <= this._rounds; round++) {
      substituteBytes(state, SBOX);
      shiftRows(state, 1);
      // The final round omits MixColumns (it would add nothing an attacker
      // cannot undo), but it still gets its round key.
      if (round !== this._rounds) mixColumns(state, [2, 3, 1, 1]);
      addRoundKey(state, this._words, round);
    }
    return state;
  }

  /**
   * @param {Uint8Array} ciphertext exactly 16 bytes
   * @returns {Uint8Array} 16 bytes
   * @throws {PyValueError} 'ciphertext block must be 16 bytes'
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new PyValueError('ciphertext block must be 16 bytes');
    }
    const state = Uint8Array.from(ciphertext);

    addRoundKey(state, this._words, this._rounds);
    for (let round = this._rounds - 1; round >= 0; round--) {
      shiftRows(state, -1);
      substituteBytes(state, INV_SBOX);
      addRoundKey(state, this._words, round);
      if (round !== 0) mixColumns(state, [14, 11, 13, 9]);
    }
    return state;
  }
}

// aes-modes.mjs
//
// Modes of operation, mirroring pyaes's `AESModeOfOperationECB` and
// `AESModeOfOperationCBC`: single-block interfaces (no padding, no buffering) that
// raise the same ValueErrors as the Python originals.

import { PyValueError } from './py-errors.mjs';
import { AES, BLOCK_SIZE } from './aes-core.mjs';

/** XOR two equal-length blocks into a fresh array. */
function xorBlock(a, b) {
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = a[i] ^ b[i];
  return out;
}

/**
 * Electronic Codebook: each block is enciphered independently, so the object
 * holds no state between calls.
 */
export class AESModeOfOperationECB {
  /** @param {Uint8Array} key 16, 24 or 32 bytes */
  constructor(key) {
    this._aes = new AES(key);
  }

  /** @param {Uint8Array} plaintext 16 bytes @returns {Uint8Array} 16 bytes */
  encrypt(plaintext) {
    return this._aes.encrypt(plaintext);
  }

  /** @param {Uint8Array} ciphertext 16 bytes @returns {Uint8Array} 16 bytes */
  decrypt(ciphertext) {
    return this._aes.decrypt(ciphertext);
  }
}

/**
 * Cipher-Block Chaining.
 *
 * The object carries the previous ciphertext block, so consecutive calls chain:
 * a single instance encrypting two blocks XORs the IV into the first block and
 * the *first ciphertext* into the second.
 */
export class AESModeOfOperationCBC {
  /**
   * @param {Uint8Array} key 16, 24 or 32 bytes
   * @param {Uint8Array} [iv] exactly 16 bytes; defaults to 16 zero bytes
   * @throws {PyValueError} 'initialization vector must be 16 bytes', or
   *         'Invalid key size' from {@link AES}
   */
  constructor(key, iv) {
    // Order matters and matches pyaes (confirmed against the reference binary):
    // the IV is validated before the key is even looked at, so a run with both
    // wrong reports the IV.
    const ivBytes = iv === undefined ? new Uint8Array(BLOCK_SIZE) : Uint8Array.from(iv);
    if (ivBytes.length !== BLOCK_SIZE) {
      throw new PyValueError('initialization vector must be 16 bytes');
    }
    this._lastCipherblock = ivBytes;
    this._aes = new AES(key);
  }

  /**
   * @param {Uint8Array} plaintext 16 bytes
   * @returns {Uint8Array} 16 bytes
   * @throws {PyValueError} 'plaintext block must be 16 bytes'
   */
  encrypt(plaintext) {
    // Checked here rather than being left to AES.encrypt: a short block would
    // otherwise be silently widened to 16 bytes by the XOR below.
    if (plaintext.length !== BLOCK_SIZE) {
      throw new PyValueError('plaintext block must be 16 bytes');
    }
    const ciphertext = this._aes.encrypt(xorBlock(plaintext, this._lastCipherblock));
    // Copy, so that a caller mutating the block it was handed cannot corrupt the
    // chaining state.
    this._lastCipherblock = ciphertext.slice();
    return ciphertext;
  }

  /**
   * @param {Uint8Array} ciphertext 16 bytes
   * @returns {Uint8Array} 16 bytes
   * @throws {PyValueError} 'ciphertext block must be 16 bytes'
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new PyValueError('ciphertext block must be 16 bytes');
    }
    const plaintext = xorBlock(this._aes.decrypt(ciphertext), this._lastCipherblock);
    this._lastCipherblock = Uint8Array.from(ciphertext);
    return plaintext;
  }
}

// pyaes.mjs
//
// Aggregator standing in for Python's `import pyaes`: it re-exports the pieces of
// the library the program touches, both as named exports and as a namespace object
// so call sites can read like the original (`pyaes.AESModeOfOperationCBC(...)`).

import { AES } from './aes-core.mjs';
import { AESModeOfOperationCBC, AESModeOfOperationECB } from './aes-modes.mjs';

export { AES } from './aes-core.mjs';
export { AESModeOfOperationCBC, AESModeOfOperationECB } from './aes-modes.mjs';

export default { AES, AESModeOfOperationCBC, AESModeOfOperationECB };

// t-aes.mjs — self-test for the `aes` track. Lives outside /output on purpose.
//
// Run: node /workspace/verify/t-aes.mjs
//
// Covers: table derivation, FIPS-197 Appendix C known-answer vectors (encrypt and
// decrypt), oracle-derived raw-ECB and CBC-chaining vectors, UTF-8 byte-length
// vectors, pyaes validation order/messages, and a live differential run against
// /workspace/dataset/test7_executable.

import { execFileSync } from 'node:child_process';
import process from 'node:process';

import { SBOX, INV_SBOX, RCON, gmul } from '/output/lib/aes-tables.mjs';
import { AES } from '/output/lib/aes-core.mjs';
import { AESModeOfOperationCBC, AESModeOfOperationECB } from '/output/lib/aes-modes.mjs';
